const watcherIDs = `-- name: WatcherIDs :many
SELECT user_id FROM watchers WHERE issue_id = $1
`

func (q *Queries) WatcherIDs(ctx context.Context, issueID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, watcherIDs, issueID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var user_id uuid.UUID
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
